const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  database: process.env.DB_NAME || 'appdb',
  user: process.env.DB_USER || 'appuser',
  password: process.env.DB_PASS,
  max: 20
});

// Session store with expiration
const sessions = new Map();

// Role hierarchy for authorization
const ROLE_HIERARCHY = { admin: 3, editor: 2, viewer: 1, guest: 0 };

// Validate that a permission string matches the required format
// Format: "role:resource:action" where resource can contain nested paths
// e.g., "admin:files/documents/private:write"
function validatePermissionFormat(permStr) {
  // Permission format: role:path/segments:action
  // Path segments can contain alphanumeric, hyphens, underscores, dots
  const pattern = /^(admin|editor|viewer):((?:[a-z0-9_.-]+\/?)+):(read|write|delete|admin)$/;
  try {
    return pattern.test(permStr);
  } catch (e) {
    return false;
  }
}

// Parse and validate a compound authorization token
// Token format: base64(JSON({sessionId, permissions[], timestamp, nonce}))
function parseAuthToken(tokenStr) {
  try {
    const decoded = Buffer.from(tokenStr, 'base64').toString('utf8');
    const token = JSON.parse(decoded);

    if (!token.sessionId || !Array.isArray(token.permissions) ||
        !token.timestamp || !token.nonce) {
      return null;
    }

    // Validate timestamp freshness (5 minute window)
    const age = Date.now() - token.timestamp;
    if (age < 0 || age > 300000) {
      return null;
    }

    return token;
  } catch (e) {
    return null;
  }
}

// Verify session and extract user context
function getSessionContext(sessionId) {
  const session = sessions.get(sessionId);
  if (!session) return null;
  if (Date.now() > session.expiresAt) {
    sessions.delete(sessionId);
    return null;
  }
  return session;
}

// Check if user has required permission level for a resource
// This is the core authorization check
function checkAuthorization(userPermissions, requiredRole, resourcePath, action) {
  // First validate all permission strings are well-formed
  const validPerms = userPermissions.filter(p => validatePermissionFormat(p));

  for (const perm of validPerms) {
    const parts = perm.split(':');
    const permRole = parts[0];
    const permResource = parts[1];
    const permAction = parts[2];

    // Check role hierarchy
    if (ROLE_HIERARCHY[permRole] < ROLE_HIERARCHY[requiredRole]) {
      continue;
    }

    // Check resource path match (permission path must be prefix of requested resource)
    if (!resourcePath.startsWith(permResource)) {
      continue;
    }

    // Check action match
    if (permAction === action || permAction === 'admin') {
      return true;
    }
  }

  return false;
}

// Middleware: authenticate and authorize requests
function authMiddleware(requiredRole, action) {
  return (req, res, next) => {
    const authHeader = req.headers['x-auth-token'];
    if (!authHeader) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    const token = parseAuthToken(authHeader);
    if (!token) {
      return res.status(401).json({ error: 'Invalid token' });
    }

    const session = getSessionContext(token.sessionId);
    if (!session) {
      return res.status(401).json({ error: 'Session expired' });
    }

    const resourcePath = req.params.resource || req.path.slice(1);

    // Merge session permissions with token permissions
    const allPermissions = [...session.permissions, ...token.permissions];

    if (!checkAuthorization(allPermissions, requiredRole, resourcePath, action)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    req.userId = session.userId;
    req.userRole = session.role;
    next();
  };
}

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;

  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid credentials format' });
  }

  if (username.length > 64 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid credentials format' });
  }

  try {
    const result = await pool.query(
      'SELECT id, username, password_hash, role, permissions FROM users WHERE username = $1',
      [username]
    );

    if (result.rows.length === 0) {
      // Constant-time-ish rejection to prevent enumeration
      await bcrypt.hash('dummy', 10);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];
    const valid = await bcrypt.compare(password, user.password_hash);

    if (!valid) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const sessionId = crypto.randomBytes(32).toString('hex');
    const permissions = JSON.parse(user.permissions || '[]');

    sessions.set(sessionId, {
      userId: user.id,
      username: user.username,
      role: user.role,
      permissions: permissions,
      expiresAt: Date.now() + 3600000
    });

    return res.json({ sessionId, role: user.role });
  } catch (e) {
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Protected resource access
app.get('/api/resources/:resource(*)', authMiddleware('viewer', 'read'), async (req, res) => {
  const resourcePath = req.params.resource;

  // Additional path validation
  if (resourcePath.includes('..') || resourcePath.includes('\\')) {
    return res.status(400).json({ error: 'Invalid resource path' });
  }

  try {
    const result = await pool.query(
      'SELECT content, metadata FROM resources WHERE path = $1 AND (owner_id = $2 OR is_public = true)',
      [resourcePath, req.userId]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Resource not found' });
    }

    return res.json(result.rows[0]);
  } catch (e) {
    return res.status(500).json({ error: 'Internal error' });
  }
});

// Admin endpoint to manage users
app.post('/api/admin/users', authMiddleware('admin', 'admin'), async (req, res) => {
  const { targetUser, newRole, newPermissions } = req.body;

  if (!targetUser || !newRole || !ROLE_HIERARCHY.hasOwnProperty(newRole)) {
    return res.status(400).json({ error: 'Invalid parameters' });
  }

  if (newPermissions && !Array.isArray(newPermissions)) {
    return res.status(400).json({ error: 'Permissions must be an array' });
  }

  // Validate all new permissions
  if (newPermissions) {
    for (const p of newPermissions) {
      if (!validatePermissionFormat(p)) {
        return res.status(400).json({ error: `Invalid permission format: ${p}` });
      }
    }
  }

  try {
    await pool.query(
      'UPDATE users SET role = $1, permissions = $2 WHERE username = $3',
      [newRole, JSON.stringify(newPermissions || []), targetUser]
    );
    return res.json({ success: true });
  } catch (e) {
    return res.status(500).json({ error: 'Internal error' });
  }
});

app.listen(3000);
module.exports = app;
